import csv
import math
import re
from datetime import datetime
from statistics import median as stats_median


def parse_amount(s):
    s = s.strip()
    if not s:
        return float('nan')

    # Determine if negative
    is_negative = False
    if 'CR' in s.upper():
        is_negative = True
    if s.startswith('(') and s.endswith(')'):
        is_negative = True
    elif s.startswith('('):
        is_negative = True
    if '-' in s:
        is_negative = True

    # Remove C1 and C2 tokens
    s = re.sub(r'\bC1\b', '', s)
    s = re.sub(r'\bC2\b', '', s)
    s = re.sub(r'C1', '', s)
    s = re.sub(r'C2', '', s)

    # Strip out all letters (except CR which we already handled) and spaces
    # Actually, let's remove all letters
    # Keep only digits, commas, dots, and minus sign? Actually step says keep only digits and "," and "."
    # Remove letters and spaces
    s = re.sub(r'[a-zA-Z\s]', '', s)

    # Now determine decimal separator using last-separator rule
    # Find last occurrence of , and .
    last_comma = s.rfind(',')
    last_dot = s.rfind('.')

    # If both exist, the last one is the decimal separator
    if last_comma >= 0 and last_dot >= 0:
        if last_comma > last_dot:
            decimal_sep = ','
            thousands_sep = '.'
        else:
            decimal_sep = '.'
            thousands_sep = ','
    elif last_comma >= 0:
        # Only comma exists
        # If exactly two digits after last comma, treat as decimal separator
        after_last = s[last_comma + 1:]
        if len(after_last) == 2 and all(c.isdigit() for c in after_last):
            decimal_sep = ','
            thousands_sep = ''
        else:
            decimal_sep = ''
            thousands_sep = ','
    elif last_dot >= 0:
        # Only dot exists
        after_last = s[last_dot + 1:]
        if len(after_last) == 2 and all(c.isdigit() for c in after_last):
            decimal_sep = '.'
            thousands_sep = ''
        else:
            decimal_sep = ''
            thousands_sep = '.'
    else:
        decimal_sep = ''
        thousands_sep = ''

    # Remove thousands separator, replace decimal separator with .
    if thousands_sep:
        s = s.replace(thousands_sep, '')
    if decimal_sep:
        s = s.replace(decimal_sep, '.')

    # Remove any remaining non-digit, non-dot, non-minus characters
    s = re.sub(r'[^0-9.\-]', '', s)

    if not s or s == '-' or s == '.':
        return float('nan')

    try:
        val = float(s)
    except ValueError:
        return float('nan')

    if is_negative:
        val = -abs(val)
    return val


def parse_notes(notes):
    items = None
    adj_pct = 0.0
    fee = 0.0
    waive = False

    m = re.search(r'items=(\d+)', notes)
    if m:
        items = int(m.group(1))

    m = re.search(r'adj=([+-]?\d+(?:\.\d+)?)%', notes)
    if m:
        adj_pct = float(m.group(1))

    m = re.search(r'fee=([+-]?\d+(?:\.\d+)?)', notes)
    if m:
        fee = float(m.group(1))

    if re.search(r'waive=true', notes, re.IGNORECASE):
        waive = True

    return items, adj_pct, fee, waive


def compute_net(base_amount, adj_pct, fee, waive):
    if math.isnan(base_amount):
        return float('nan')
    if waive:
        return 0.0
    return base_amount * (1.0 + adj_pct / 100.0) + fee


def mad(data):
    if not data:
        return 0.0
    med = stats_median(data)
    return stats_median([abs(x - med) for x in data])


def main():
    rows = []
    with open('/app/dataset/data.csv', 'r') as f:
        reader = csv.DictReader(f)
        for i, row in enumerate(reader):
            record_id = row['record_id'].strip()
            event_time_str = row['event_time'].strip()
            region = row['region'].strip()
            channel = row['channel'].strip()
            amount_str = row['amount_str']
            notes = row['notes']

            base_amount = parse_amount(amount_str)
            items, adj_pct, fee, waive = parse_notes(notes)
            net = compute_net(base_amount, adj_pct, fee, waive)

            rows.append({
                'record_id': record_id,
                'event_time_str': event_time_str,
                'region': region,
                'channel': channel,
                'base_amount': base_amount,
                'items': items,
                'adj_pct': adj_pct,
                'fee': fee,
                'waive': waive,
                'net': net,
                'file_order': i
            })

    # Parse event_time
    for r in rows:
        et = r['event_time_str']
        if et:
            r['event_time'] = datetime.strptime(et, '%Y-%m-%dT%H:%M:%SZ')
        else:
            r['event_time'] = None

    # Dedup by record_id: keep latest event_time, break ties by preferring real net, then earlier file_order
    deduped = {}
    for r in rows:
        rid = r['record_id']
        if rid in deduped:
            existing = deduped[rid]
            # Compare event_time
            if r['event_time'] is not None and existing['event_time'] is not None:
                if r['event_time'] > existing['event_time']:
                    deduped[rid] = r
                elif r['event_time'] == existing['event_time']:
                    # Prefer real net over NaN/None
                    r_has_net = not math.isnan(r['net'])
                    e_has_net = not math.isnan(existing['net'])
                    if r_has_net and not e_has_net:
                        deduped[rid] = r
                    elif r_has_net == e_has_net:
                        if r['file_order'] < existing['file_order']:
                            deduped[rid] = r
            elif r['event_time'] is not None and existing['event_time'] is None:
                deduped[rid] = r
            elif r['event_time'] is None and existing['event_time'] is not None:
                pass
            else:
                # Both None - ambiguous, keep earlier file_order
                if r['file_order'] < existing['file_order']:
                    deduped[rid] = r
        else:
            deduped[rid] = r

    rows = list(deduped.values())

    # Filter
    # Note: we need to work with original file before dedup for "earlier file order" tie-breaking, but the spec says "keep one row per record_id by choosing the latest event_time, breaking ties by preferring the version with a real net result, then earlier file order"
    # So the file_order is already used in dedup.

    filtered = []
    for r in rows:
        if r['event_time'] is None:
            continue
        et = r['event_time']
        start = datetime(2025, 10, 1, 0, 0, 0)
        end = datetime(2025, 12, 31, 23, 59, 59)
        if not (start <= et <= end):
            continue
        if r['channel'].lower() == 'phone':
            continue
        if math.isnan(r['net']) or math.isinf(r['net']):
            continue
        filtered.append(r)

    rows = filtered

    # Compute month
    for r in rows:
        r['month'] = r['event_time'].strftime('%Y-%m')

    # Group by region, month
    groups = {}
    for r in rows:
        key = (r['region'], r['month'])
        groups.setdefault(key, []).append(r)

    # Compute robust z-scores
    for key, group in groups.items():
        nets = [g['net'] for g in group]
        med = stats_median(nets)
        m = mad(nets)
        if m == 0:
            for g in group:
                g['robust_z'] = 0.0
        else:
            for g in group:
                g['robust_z'] = 0.6745 * (g['net'] - med) / m

    # Compute items_eff and anomaly_score
    for r in rows:
        items_eff = r['items'] if r['items'] is not None else 1
        items_eff = max(items_eff, 1)
        r['items_eff'] = items_eff
        r['anomaly_score'] = abs(r['robust_z']) * math.log1p(items_eff)

    # Sort
    rows.sort(key=lambda r: (
        -r['anomaly_score'],
        -abs(r['robust_z']),
        -r['event_time'].timestamp(),
        r['record_id']
    ), kind='mergesort')

    top10 = [r['record_id'] for r in rows[:10]]
    return top10


def answer() -> list[str]:
    return main()


if __name__ == '__main__':
    import json
    with open('/app/answer.json', 'w') as f:
        json.dump(answer(), f, default=list)
